D.DynamicSpellTexts[86933]={Description={Key="8a9104b7a25f63f0:98",Text="永久性地为一件头部装备附魔，使其获得力量+{1}、精通+{2}的效果。\r\n\r\n附魔之后，该装备会与你绑定。",Count=2,Constants={},Equals={}}}
D.DynamicSpellTexts[86934]={Description={Key="c3880f4b595e534e:95",Text="永久性地为一件头部装备附魔，使其获得敏捷+{1}、急速+{2}的效果。\r\n\r\n附魔之后，该装备会与你绑定。",Count=2,Constants={},Equals={}}}
D.DynamicSpellTexts[86963]={Description={Key="b5942be98774c0ce:30",Text="使通过任务获得的经验提高{1}%。",Count=1,Constants={},Equals={}},Aura={Key="7163c4483645f4c7:143",Text="你最近阅读了一些有趣的故事，讲述某人试图重新收集《荆棘谷的青山》，最后以失败告终。通过任务获得的经验提高{1}%。",Count=1,Constants={},Equals={}}}
D.DynamicSpellTexts[86972]={Aura={Key="cc9deb8d7c2a50b6:172",Text="虽然有些枯燥，不过还是有些收获。你对周围的地形异常熟悉。移动速度提高{1}%。不与其它提高移动速度的效果叠加。",Count=1,Constants={},Equals={}}}
D.DynamicSpellTexts[86974]={Aura={Key="e69939ed6832a614:133",Text="并不是吹嘘，你最近阅读了一些和恶魔的大规模战斗故事，使你在战场上获得显著优势。对恶魔造成的伤害提高{1}%。",Count=1,Constants={},Equals={}}}
D.DynamicSpellTexts[86975]={Aura={Key="32f06a347de7285f:88",Text="你受到了屠龙英勇事迹的鼓舞。对龙类造成的伤害提高{1}%。",Count=1,Constants={},Equals={}}}
D.DynamicSpellTexts[86976]={Aura={Key="f427f245f2493504:95",Text="火与水，大地和空气；你受到了启发。对元素造成的伤害提高{1}%。",Count=1,Constants={},Equals={}}}
D.DynamicSpellTexts[86977]={Aura={Key="25b55ae89b41130d:98",Text="你刚刚读到了一些有趣的方法，教你如何打倒不可一世的巨人。对巨人造成的伤害提高{1}%。",Count=1,Constants={},Equals={}}}
D.DynamicSpellTexts[86980]={Aura={Key="66fae742043c2339:157",Text="你刚刚读了一个残忍杀手的日记。虽然上面到处沾着血迹，不过你还是掌握了要领。对人型生物造成的伤害提高{1}%。",Count=1,Constants={},Equals={}}}
D.DynamicSpellTexts[86982]={Aura={Key="57a7ec54253cebcb:131",Text="你刚刚阅读了一个机械天才的日记，他是《魔能机甲维修窍门大全》的作者。对机械造成的伤害提高{1}%。",Count=1,Constants={},Equals={}}}
D.DynamicSpellTexts[86983]={Aura={Key="0b0ca0902017f75f:116",Text="你最近阅读了一个冒险者未完成的冒险指南，讲述了一段他如何在僵尸袭击下幸免于难的经历。对亡灵造成的伤害提高{1}%。",Count=1,Constants={},Equals={}}}
